import {LABELS} from './model.js';
export class Renderer {
 constructor(canvas){this.canvas=canvas;this.c=canvas.getContext('2d');this.previousX=null;this.visualX=null;}
 draw(s,t){const c=this.c;const W=1000,H=540;c.clearRect(0,0,W,H);const gradient=c.createLinearGradient(0,0,0,H);gradient.addColorStop(0,'#ececdf');gradient.addColorStop(1,'#e2e4d2');c.fillStyle=gradient;c.fillRect(0,0,W,H);
 // softly lit wallpaper, shadows and a framed botanical print
 for(let x=36;x<1000;x+=80){c.strokeStyle='#d8deca77';c.lineWidth=1;c.beginPath();c.moveTo(x,0);c.lineTo(x,350);c.stroke();}
 this.round(450,34,107,122,5,'#c8cbb4');this.round(456,39,95,110,2,'#f5f2df');c.strokeStyle='#8b9c71';c.lineWidth=3;c.beginPath();c.moveTo(504,128);c.bezierCurveTo(484,90,526,74,501,54);c.stroke();for(let k=0;k<5;k++){const x=500+(k%2?9:-9),y=65+k*11;c.fillStyle=k%2?'#95a17a':'#b2ba8e';c.beginPath();c.ellipse(x,y,11,5,k%2?-.65:.65,0,Math.PI*2);c.fill();}
 c.fillStyle='#c3c4a4';c.beginPath();c.moveTo(0,352);c.lineTo(W,352);c.lineTo(W,540);c.lineTo(0,540);c.fill();
 const floor=c.createLinearGradient(0,350,0,540);floor.addColorStop(0,'#e4cba0');floor.addColorStop(1,'#d9ba87');c.fillStyle=floor;c.fillRect(0,369,W,171);
 // bedding texture: deterministic, never random-flickering
 for(let i=0;i<440;i++){const x=(i*137.73)%1000,y=376+(i*43.19)%154;c.strokeStyle=i%3?'#bd9e6d55':'#fff1c255';c.lineWidth=2;c.beginPath();c.moveTo(x,y);c.lineTo(x+5+(i%9),y-2+i%6);c.stroke();}
 this.shadow(160,425,130,23);this.house(s.cage.home,s.cage.nest,s.cage.stash);this.wheel(s.cage.wheel,t,s.pet.state==='wheel'&&Math.abs(s.pet.x-s.cage.wheel)<10);
 this.bowl(s.cage.bowl,s.cage.food);this.bottle(s.cage.bottle,s.cage.water);
 // a little wooden bridge and a seed
 this.shadow(570,427,58,12);c.fillStyle='#b28e60';c.beginPath();c.ellipse(565,418,47,28,0,Math.PI,0);c.lineTo(612,430);c.lineTo(518,430);c.fill();for(let i=0;i<7;i++)this.round(523+i*12,394+Math.abs(3-i)*5,9,31,4,'#caa779');
 const p=s.pet;if(this.visualX===null)this.visualX=p.x;this.visualX+=(p.x-this.visualX)*.11;
 const atHome=(p.state==='sleep'||p.state==='hide')&&Math.abs(p.x-s.cage.home)<8;
 const atWheel=p.state==='wheel'&&Math.abs(p.x-s.cage.wheel)<8;
 if(atHome){c.fillStyle='#f4dfb7';c.font='italic 23px Georgia';c.fillText('z',s.cage.home+5,310-Math.sin(t*.001)*6);c.font='italic 17px Georgia';c.fillText('z',s.cage.home+25,291-Math.sin(t*.001+1)*5);}
 else if(!s.alive){this.hamster(this.visualX,435,t,1,false,true);}
 else{const moving=Math.abs(p.x-p.target)>3||Math.abs(this.visualX-p.x)>3;const y=atWheel?345:431;this.hamster(this.visualX,y,t,p.direction,moving,false,p.state,p.carry);}
 // transparent front glass rim
 c.strokeStyle='#fff9';c.lineWidth=8;c.beginPath();c.moveTo(9,25);c.lineTo(9,499);c.quadraticCurveTo(9,529,39,529);c.lineTo(963,529);c.quadraticCurveTo(991,529,991,499);c.lineTo(991,25);c.stroke();c.strokeStyle='#a8af9877';c.lineWidth=1;c.strokeRect(17,18,966,503);
 c.fillStyle='#fff3';c.beginPath();c.moveTo(28,50);c.lineTo(58,50);c.lineTo(210,516);c.lineTo(180,516);c.fill();
 if(!s.alive){c.fillStyle='#f6f3eccc';c.fillRect(0,0,1000,540);c.textAlign='center';c.fillStyle='#58634d';c.font='32px Georgia';c.fillText('Пончик останется в вашей памяти',500,260);c.font='17px system-ui';c.fillText('Его история сохранена в дневнике',500,300);c.textAlign='left';}
 }
 round(x,y,w,h,r,color){const c=this.c;c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
 shadow(x,y,rx,ry){const c=this.c;c.save();c.filter='blur(9px)';c.fillStyle='#64573735';c.beginPath();c.ellipse(x,y,rx,ry,0,0,7);c.fill();c.restore();}
 house(x,nest,stash){const c=this.c;this.round(x-101,285,202,139,8,'#bd8d5e');this.round(x-92,288,184,127,5,'#d2ad79');for(let y=305;y<420;y+=27){c.strokeStyle='#ad835345';c.beginPath();c.moveTo(x-90,y);c.lineTo(x+90,y);c.stroke();}c.fillStyle='#9a7754';c.beginPath();c.moveTo(x-120,291);c.lineTo(x,203);c.lineTo(x+122,291);c.closePath();c.fill();c.fillStyle='#b18c61';c.beginPath();c.moveTo(x-120,282);c.lineTo(x,194);c.lineTo(x+122,282);c.lineTo(x+115,295);c.lineTo(x,215);c.lineTo(x-114,295);c.fill();c.fillStyle='#6e5842';c.beginPath();c.roundRect(x-37,333,74,91,[36,36,0,0]);c.fill();c.fillStyle='#d3b77c';for(let i=0;i<3+Math.floor(nest/10);i++){c.beginPath();c.ellipse(x-36+i*8,420+(i%2)*4,12,3,-.2,0,7);c.fill();}for(let i=0;i<Math.min(12,Math.ceil(stash));i++){c.fillStyle=i%2?'#daba72':'#e8cf94';c.beginPath();c.ellipse(x-24+(i*9)%45,405+Math.floor(i/5)*4,3,2,i,0,7);c.fill();}this.round(x+50,310,26,25,5,'#8c7353');c.strokeStyle='#d5bb86';c.lineWidth=3;c.beginPath();c.moveTo(x+63,311);c.lineTo(x+63,334);c.moveTo(x+51,322);c.lineTo(x+75,322);c.stroke();}
 wheel(x,t,running){const c=this.c;this.shadow(x,434,102,14);c.strokeStyle='#8b9674';c.lineWidth=11;c.beginPath();c.moveTo(x-50,430);c.lineTo(x,310);c.lineTo(x+53,430);c.stroke();this.round(x-70,425,140,12,5,'#899474');c.save();c.translate(x,295);c.rotate(running?t*.004:0);c.fillStyle='#d0d7bb';c.beginPath();c.arc(0,0,108,0,7);c.fill();c.strokeStyle='#879776';c.lineWidth=13;c.stroke();c.strokeStyle='#a8b593';c.lineWidth=4;for(let i=0;i<12;i++){const a=i*Math.PI/6;c.beginPath();c.moveTo(Math.cos(a)*95,Math.sin(a)*95);c.lineTo(Math.cos(a)*102,Math.sin(a)*102);c.stroke();}for(let i=0;i<5;i++){c.rotate(Math.PI*2/5);c.beginPath();c.moveTo(0,0);c.lineTo(97,0);c.stroke();}c.fillStyle='#7b8e66';c.beginPath();c.arc(0,0,12,0,7);c.fill();c.restore();}
 bowl(x,food){const c=this.c;this.shadow(x,439,58,10);this.round(x-54,407,108,36,15,'#9d715c');c.fillStyle='#c69576';c.beginPath();c.ellipse(x,407,54,17,0,0,7);c.fill();c.fillStyle='#7e5e42';c.beginPath();c.ellipse(x,407,43,11,0,0,7);c.fill();for(let i=0;i<Math.floor(food*.45);i++){c.fillStyle=['#dfbd72','#be954f','#ecd49a'][i%3];c.beginPath();c.ellipse(x-34+(i*17)%68,401+(i*7)%12,4,2,i,0,7);c.fill();}}
 bottle(x,water){const c=this.c;this.round(x-25,133,50,133,17,'#ecf5e6aa');c.save();c.beginPath();c.roundRect(x-21,138,42,121,12);c.clip();c.fillStyle='#a1c3c1aa';c.fillRect(x-21,259-water*1.18,42,water*1.18);c.restore();this.round(x-27,127,54,19,7,'#789183');c.strokeStyle='#a7afa1';c.lineWidth=7;c.beginPath();c.moveTo(x,264);c.lineTo(x,318);c.lineTo(x-15,335);c.stroke();c.strokeStyle='#fff7';c.lineWidth=4;c.beginPath();c.moveTo(x-13,155);c.lineTo(x-13,224);c.stroke();c.fillStyle='#7f907a';c.font='10px system-ui';c.fillText('ВОДА',x-15,194);}
 hamster(x,y,t,dir,moving,dead=false,state='explore',carry=0){const c=this.c;const bob=moving?Math.sin(t*.018)*3:Math.sin(t*.003)*1.3;this.shadow(x,y+3,48,9);c.save();c.translate(x,y+bob);c.scale(dir,1);c.fillStyle='#c7a37b';c.beginPath();c.ellipse(-39,-15,10,5,-.4,0,7);c.fill();const fur=c.createRadialGradient(-9,-39,2,0,-25,59);fur.addColorStop(0,'#e5c79e');fur.addColorStop(1,'#ad7a4e');c.fillStyle=fur;c.beginPath();c.ellipse(-6,-30,44,35,-.12,0,7);c.fill();c.fillStyle='#f5e8cc';c.beginPath();c.ellipse(7,-15,29,20,0,0,7);c.fill();c.fillStyle='#e6b2a2';for(const px of [-22,22]){c.beginPath();c.ellipse(px,-1+Math.sin(t*.02+px)*(moving?4:0),10,5,0,0,7);c.fill();}c.fillStyle='#c39166';c.beginPath();c.ellipse(23,-61,14,16,-.2,0,7);c.fill();c.fillStyle='#e9b8a6';c.beginPath();c.ellipse(24,-61,8,10,-.2,0,7);c.fill();c.fillStyle='#ddba8d';c.beginPath();c.ellipse(29,-31,27,27,0,0,7);c.fill();if(carry>0){c.fillStyle='#ecd1ab';c.beginPath();c.ellipse(36,-21,20+carry*.6,18,0,0,7);c.fill();}c.fillStyle='#f6e6c8';c.beginPath();c.ellipse(45,-19,16,12,0,0,7);c.fill();c.fillStyle='#302d25';c.beginPath();if(dead){c.strokeStyle='#615342';c.lineWidth=2;c.moveTo(33,-36);c.lineTo(41,-36);c.stroke();}else{const blink=t%4700>4510;c.ellipse(37,-36,blink?4:4,blink?1:5,0,0,7);c.fill();if(!blink){c.fillStyle='#fff';c.beginPath();c.arc(38,-38,1.4,0,7);c.fill();}}c.fillStyle='#c5827a';c.beginPath();c.ellipse(59,-22,4,3,0,0,7);c.fill();c.strokeStyle='#806c5288';c.lineWidth=1;for(let i=0;i<3;i++){c.beginPath();c.moveTo(48,-19+i*3);c.lineTo(70,-26+i*7);c.stroke();}if((state==='eat'||state==='eatStash')&& !moving){c.fillStyle='#e6cb7b';c.beginPath();c.ellipse(48,-7,5,8,.6,0,7);c.fill();}if((state==='groom'||state==='nest'||state==='gather')&&!moving){c.fillStyle='#ecc1aa';c.beginPath();c.ellipse(40,-31+Math.sin(t*.02)*6,10,5,-.8,0,7);c.fill();}c.restore();}
}
